interface TurnArgs {
  user: { id: string };
  body: RequestBody;
  messages: Array<{ role: "system" | "user" | "assistant"; content: string }>;
  modelId: string;
  provider: Provider;
  baseURL: string;
  key: string;
  setPhase: (phase: string) => Promise<void>;
  setPartial: (text: string) => Promise<void>;
  isCancelled: () => Promise<boolean>;
}

/** The whole turn: cards -> tool loop (<= 2 memory actions) -> streamed answer.
 *  Phase + partial-text reporting and cancellation checks (job mode). */
async function runTurn(a: TurnArgs): Promise<string> {
  const { user, body, modelId, provider, baseURL, key, setPhase, setPartial, isCancelled } = a;

  // --- Which chat is this? A declared being wakes with its memory tools. ---
  const hasThread = typeof body.threadId === "string" && body.threadId.trim() !== "";
  let being = null as Awaited<ReturnType<typeof getBeingForThread>>;
  if (hasThread) {
    try {
      being = await getBeingForThread(user.id, (body.threadId as string).trim());
    } catch (e) {
      console.error("[chat] being lookup failed:", (e as Error).message);
    }
  }

  // --- Cards: persona preset (client) FIRST, memory card (server) SECOND ---
  const personaCards = a.messages.filter((m) => m.role === "system").map((m) => m.content);
  let memoryCard: string | null = null;
  if (being && being.recallEnabled) memoryCard = limbsPrompt(being);
  else if (!being && hasThread) memoryCard = assistantMemoryPrompt();
  const systemText = [...personaCards, ...(memoryCard ? [memoryCard] : [])].join("\n\n");
  const convo = a.messages
    .filter((m) => m.role !== "system")
    .map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));

  // --- Tools + hard-stop context (what the model can already see) ---
  const tzOff =
    typeof body.tzOffsetMinutes === "number" && isFinite(body.tzOffsetMinutes)
      ? Math.max(-840, Math.min(840, body.tzOffsetMinutes))
      : 0;
  const view = hasThread
    ? {
        currentThreadId: (body.threadId as string).trim(),
        contextTexts: new Set(convo.map((m) => normalizeForContext(m.content || ""))),
      }
    : undefined;
  const tools = hasThread ? buildMemoryTools({ uid: user.id, being, tzOff, view }) : {};
  const hasTools = Object.keys(tools).length > 0;

  // --- Model: OpenAI-compatible provider (Venice or OpenRouter) ---
  const model = modelFor(provider, baseURL, key, modelId);
  const providerOptions = providerOptionsFor(provider);

  // Cancellation: the client flips the job to "cancelled"; we poll and abort.
  const ac = new AbortController();
  const cancelTimer = setInterval(() => {
    void isCancelled().then((c) => { if (c) ac.abort(); });
  }, 2000);

  // Beam scales to zero: after a quiet spell the first token can take a minute while the
  // GPU container wakes (snapshot restore) — tell the friend instead of looking frozen.
  await setPhase(provider === "beam" ? "waking the being's mind (first message after a pause can take a minute)" : "thinking");
  try {
    const result = streamText({
      model,
      system: systemText || undefined,
      messages: convo,
      tools: hasTools ? tools : undefined,
      stopWhen: stepCountIs(3), // up to two memory actions, then the answer
      providerOptions,
      includeRawChunks: provider === "venice",
      abortSignal: ac.signal,
    });

    let text = "";
    let lastFlush = 0;
    let citations: Citation[] = [];
    for await (const part of result.fullStream) {
      switch (part.type) {
        case "start-step":
          text = ""; // only the LAST step's text is the answer
          break;
        case "tool-call":
          await setPhase(phaseForTool(part.toolName));
          if (text) { text = ""; await setPartial(""); }
          break;
        case "text-start":
          await setPhase("answering");
          break;
        case "text-delta":
          text += part.text;
          if (Date.now() - lastFlush > 400) {
            lastFlush = Date.now();
            await setPartial(text);
          }
          break;
        case "raw": {
          const c = citationsFromRaw(part.rawValue);
          if (c) citations = c;
          break;
        }
        case "error":
          throw part.error instanceof Error ? part.error : new Error(String(part.error));
        default:
          break;
      }
    }
    if (ac.signal.aborted) return "(stopped)";
    if (!text.trim()) {
      text = "I reached for my memory but ran out of steps this turn — ask me again and I'll look.";
    }
    return linkifyCitations(text, citations);
  } catch (e) {
    if (ac.signal.aborted) return "(stopped)";
    throw e;
  } finally {
    clearInterval(cancelTimer);
  }
}
